import{_ as s,l as o,o as a,c as r,v as d,p as l,x as t,d as n,i as u,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"udev 与热插拔","description":"","frontmatter":{"title":"udev 与热插拔","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/udev-hotplug.md","filePath":"cs/udev-hotplug.md","lastUpdated":1789023840000}'),v={name:"cs/udev-hotplug.md"};function p(h,e,m,f,_,E){const i=o("Mermaid");return a(),r("div",null,[e[1]||(e[1]=d('<h1 id="udev-与热插拔" tabindex="-1">udev 与热插拔 <a class="header-anchor" href="#udev-与热插拔" aria-label="Permalink to &quot;udev 与热插拔&quot;">​</a></h1><div class="epigraph"><p>内核通过 uevent 把设备增删广播出去；udev 在用户态命名节点、加载固件、跑规则，而不把策略写死在内核。</p><footer>—— 据 Linux hotplug/uevent 文档；systemd-udevd；[设备模型](/cs/device-model-binding) 为先修</footer></div><p><a href="/cs/chardev-ioctl">上一课</a>留下的缺口接到本课。 <a href="/cs/device-nodes">设备节点</a> 要有名字。<a href="/cs/device-model-binding">probe</a> 产生 <strong>uevent</strong>。缺口是 udev：规则、<code>/dev</code> 动态、固件加载。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内核发 netlink uevent。udev：匹配 ATTR、创建 <code>/dev/disk/by-uuid</code>、<code>RUN</code> 脚本。缺口：与 <a href="/cs/initramfs-pivot">initramfs</a> 里的早期 udev；规则错误可改权限导致安全问题。本课不把所有规则写成发行版文档。</p><p><span class="marginnote">devtmpfs 先由内核造节点，udev 再改名/链。固件：<code>/lib/firmware</code> 经 sysfs 请求。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>uevent → udevd 匹配 → 节点与 systemd 设备单元。对照 <a href="/cs/inotify">inotify</a>：一个文件树，一个设备树。对照 netns：udev 通常在初始 ns。对照 <a href="/cs/scsi-stack">SCSI</a>：扫描完成才有盘事件。</p>',8)),(a(),l(c,null,{default:t(()=>[u(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E5%86%85%E6%A0%B8%20uevent%22%5D%20--%3E%20U%5B%22udevd%22%5D%0A%20%20U%20--%3E%20DEV%5B%22%2Fdev%20%E8%8A%82%E7%82%B9%E4%B8%8E%E7%AC%A6%E5%8F%B7%E9%93%BE%22%5D%0A%20%20U%20--%3E%20FW%5B%22%E5%8A%A0%E8%BD%BD%E5%9B%BA%E4%BB%B6%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=d('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>udev 把命名策略放用户态，内核只报事实。这是热插拔可管理的原因。不要写成桌面自动挂载广告。与 <a href="/cs/lsm-selinux">LSM</a>：新节点的标签要规则配合。</p><p>风暴：USB 枚举可打满 udev 队列。</p><p>实现上：规则里的 NAME= 与 devtmpfs 冲突时以策略为准，写错会把盘节点改成不可预测的名字。固件加载失败则设备 probe 失败，表现为「没有网卡」。 读法上只引用<a href="/cs/chardev-ioctl">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>udev 与热插拔</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 TAG。不保证容器内 mknod 与宿主机 udev 的关系写完。下一课整机睡眠：挂起与恢复。</p><p>版本字段会变，课序钉的是机制对象「udev 与热插拔」，不是某一主线内核的结构体名。 后课默认：设备名由 uevent+udev 策略产生。休眠时驱动如何冻结，下一课 suspend。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>uevent 出核，udev 命名并加载固件。</li><li>策略在用户态规则，不在驱动里写死。</li><li>挂起恢复是下一课。</li><li>出处：udev；uevent；systemd-udevd。</li></ul>',11))])}const b=s(v,[["render",p]]);export{B as __pageData,b as default};
